<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { message } from 'ant-design-vue';
import { IconifyIcon } from '@vben/icons';
import { VbenAvatar, VbenButton, useVbenModal } from '@vben/common-ui';
import { useUserStore } from '@vben/stores';
import { useVbenForm } from '#/adapter/form';
import { requestClient } from '#/api/request';
import { useAuthStore } from '#/store';
interface AdminProfile { id:string;username:string;realName:string;avatar:string;roles:string[];email:string;emailVerified:boolean; }
const loading=ref(false),saving=ref(false),uploading=ref(false),emailSending=ref(false),emailVerifying=ref(false);
const email=ref(''),emailCode=ref(''),emailVerified=ref(false);
const profile=reactive<AdminProfile>({id:'',username:'',realName:'',avatar:'',roles:[],email:'',emailVerified:false});
const userStore=useUserStore(),authStore=useAuthStore();const passwordSaving=ref(false);
const [PasswordModal,passwordModalApi]=useVbenModal({title:'修改登录密码',onConfirm:submitPassword});
const [ProfileForm,profileFormApi]=useVbenForm({commonConfig:{componentProps:{class:'w-full'}},layout:'vertical',showDefaultActions:false,wrapperClass:'grid-cols-1',schema:[{component:'Input',fieldName:'realName',label:'昵称',componentProps:{maxlength:80,placeholder:'请输入显示昵称'}}]});
const [AvatarForm]=useVbenForm({commonConfig:{componentProps:{class:'w-full'}},layout:'vertical',showDefaultActions:false,wrapperClass:'grid-cols-1',schema:[{component:'Upload',fieldName:'avatarFile',label:'头像上传',componentProps:{accept:'image/jpeg,image/png,image/webp,image/gif,image/bmp,image/tiff,image/avif,image/heic,image/heif',listType:'picture',maxCount:1,showUploadList:false,beforeUpload:uploadAvatar}}]});
const [PasswordForm,passwordFormApi]=useVbenForm({commonConfig:{componentProps:{class:'w-full'}},layout:'vertical',showDefaultActions:false,wrapperClass:'grid-cols-1',schema:[{component:'InputPassword',fieldName:'currentPassword',label:'当前密码',componentProps:{autocomplete:'current-password',placeholder:'请输入当前密码'}},{component:'InputPassword',fieldName:'newPassword',label:'新密码',componentProps:{autocomplete:'new-password',placeholder:'至少 12 位'}},{component:'InputPassword',fieldName:'confirmPassword',label:'确认新密码',componentProps:{autocomplete:'new-password',placeholder:'再次输入新密码'}}]});
function roleLabel(){return profile.roles.some(x=>['super','SUPER_ADMIN','admin'].includes(x))?'超级管理员':'管理员';}
async function loadProfile(){loading.value=true;try{const data=await requestClient.get<AdminProfile>('/user/info');Object.assign(profile,data);email.value=data.email||'';emailVerified.value=!!data.emailVerified;await profileFormApi.setValues({realName:data.realName||''});userStore.setUserInfo(data as any);}catch{message.error('个人资料加载失败');}finally{loading.value=false;}}
async function saveProfile(){const {valid}=await profileFormApi.validate();if(!valid)return;const values=await profileFormApi.getValues();saving.value=true;try{const result=await requestClient.put<{realName:string;avatar:string}>('/user/profile',{realName:String(values.realName||'').trim(),avatar:profile.avatar});profile.realName=result.realName;profile.avatar=result.avatar;const updated=await requestClient.get<AdminProfile>('/user/info');Object.assign(profile,updated);userStore.setUserInfo(updated as any);message.success('个人资料已保存');}catch(error:any){message.error(error?.response?.data?.message||'保存个人资料失败');}finally{saving.value=false;}}
async function uploadAvatar(file:any){const image=file?.originFileObj||file;if(!(image instanceof Blob)){message.error('无法读取所选头像文件');return false;}if(image.size>20*1024*1024){message.warning('头像文件不能超过 20 MB');return false;}uploading.value=true;try{const body=new FormData();body.append('file',image,image.name||'avatar');const result=await requestClient.post<{avatar:string}>('/user/avatar',body,{headers:{'Content-Type':'multipart/form-data'}});profile.avatar=result.avatar;message.success('头像上传成功，请点击保存资料应用');}catch(error:any){message.error(error?.response?.data?.message||'头像上传失败');}finally{uploading.value=false;}return false;}
async function sendEmailCode(){if(!email.value.trim()){message.warning('请先填写邮箱地址');return;}emailSending.value=true;try{await requestClient.post('/user/email/send-code',{email:email.value.trim()});message.success('验证码已发送，请检查邮箱');}catch(error:any){message.error(error?.response?.data?.message||'验证码发送失败，请检查 SMTP 设置');}finally{emailSending.value=false;}}
async function verifyEmail(){if(!email.value.trim()||!/^\d{6}$/.test(emailCode.value)){message.warning('请填写邮箱和 6 位验证码');return;}emailVerifying.value=true;try{await requestClient.post('/user/email/verify',{email:email.value.trim(),code:emailCode.value.trim()});emailVerified.value=true;message.success('邮箱绑定成功');await loadProfile();}catch(error:any){message.error(error?.response?.data?.message||'邮箱验证失败');}finally{emailVerifying.value=false;}}
function openPasswordModal(){void passwordFormApi.setValues({currentPassword:'',newPassword:'',confirmPassword:''});passwordModalApi.open();}
async function submitPassword(){const {valid}=await passwordFormApi.validate();if(!valid)return;const values=await passwordFormApi.getValues();if(String(values.newPassword||'').length<12){message.warning('新密码至少需要 12 位');return;}if(values.newPassword!==values.confirmPassword){message.warning('两次输入的新密码不一致');return;}passwordSaving.value=true;try{await requestClient.post('/admin/password',{currentPassword:values.currentPassword,newPassword:values.newPassword});passwordModalApi.close();message.success('密码修改成功，请使用新密码重新登录');await authStore.logout();}catch(error:any){message.error(error?.response?.data?.message||'密码修改失败');}finally{passwordSaving.value=false;}}
onMounted(loadProfile);
</script>
<template>
<div class="mx-auto flex w-full min-w-0 max-w-5xl flex-col gap-4 p-3 md:p-6">
 <a-card :bordered="false" :loading="loading"><div class="flex min-w-0 flex-col items-center gap-4 sm:flex-row"><VbenAvatar :src="profile.avatar||undefined" class="size-20 shrink-0"/><div class="min-w-0 flex-1 text-center sm:text-left"><div class="break-all text-lg font-semibold">{{profile.realName||profile.username||'管理员'}}</div><div class="mt-1 break-all text-sm text-gray-500">账号：{{profile.username}}</div><div class="mt-2 flex flex-wrap justify-center gap-2 sm:justify-start"><a-tag color="blue">{{roleLabel()}}</a-tag><a-tag color="success">账户正常</a-tag></div></div><div class="w-full sm:w-auto"><AvatarForm/><a-spin v-if="uploading" size="small"/></div></div></a-card>
 <div class="grid grid-cols-1 gap-4 md:grid-cols-2">
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:shield-lock-outline" class="text-xl"/></span><span>账号与安全</span></div></template><div class="space-y-3 text-sm"><div class="flex justify-between gap-3"><span class="text-gray-500">登录账号</span><span class="break-all font-medium">{{profile.username}}</span></div><div class="flex justify-between gap-3"><span class="text-gray-500">账户角色</span><span class="font-medium">{{roleLabel()}}</span></div><div class="flex justify-between gap-3"><span class="text-gray-500">邮箱状态</span><a-tag :color="emailVerified?'success':'default'">{{emailVerified?'已验证':'未绑定'}}</a-tag></div></div></a-card>
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:account-edit-outline" class="text-xl"/></span><span>基本资料</span></div></template><ProfileForm/><div class="mt-4 flex justify-end"><VbenButton type="primary" :loading="saving" @click="saveProfile">保存资料</VbenButton></div></a-card>
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:email-check-outline" class="text-xl"/></span><span>邮箱绑定</span></div></template><a-alert v-if="emailVerified" type="success" show-icon message="邮箱已完成验证" class="mb-3"/><a-form layout="vertical"><a-form-item label="邮箱地址"><a-input v-model:value="email" type="email" placeholder="请输入常用邮箱" :disabled="emailVerified"/></a-form-item><a-form-item v-if="!emailVerified" label="邮箱验证码"><div class="flex gap-2"><a-input v-model:value="emailCode" maxlength="6" inputmode="numeric" placeholder="6 位验证码"/><a-button :loading="emailSending" @click="sendEmailCode">发送验证码</a-button></div></a-form-item></a-form><div v-if="!emailVerified" class="flex justify-end"><a-button type="primary" :loading="emailVerifying" @click="verifyEmail">验证并绑定</a-button></div><div v-else class="text-xs text-gray-500">已绑定：{{email}}</div></a-card>
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:lock-reset" class="text-xl"/></span><span>修改密码</span></div></template><div class="mb-4 text-sm leading-6 text-gray-500">建议使用至少 12 位的独立密码，并定期更新，避免与其他网站共用。</div><div class="flex justify-end"><a-button type="primary" @click="openPasswordModal">修改登录密码</a-button></div></a-card>
 </div>
 <PasswordModal class="w-full max-w-lg" :confirm-loading="passwordSaving"><div class="p-4 sm:p-6"><PasswordForm/></div></PasswordModal>
</div>
</template>